-- v3e01_normalization_practice/challenge — counter cache, owner, reconciliation
ALTER TABLE sf_shipments ADD COLUMN leg_count int NOT NULL DEFAULT 0;

UPDATE sf_shipments s
SET leg_count = coalesce(c.n, 0)
FROM (SELECT shipment_id, count(*) AS n FROM sf_legs GROUP BY shipment_id) c
WHERE c.shipment_id = s.shipment_id;

CREATE FUNCTION sf_leg_count_sync() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP IN ('DELETE', 'UPDATE') THEN
    UPDATE sf_shipments SET leg_count = leg_count - 1
    WHERE shipment_id = OLD.shipment_id;
  END IF;
  IF TG_OP IN ('INSERT', 'UPDATE') THEN
    UPDATE sf_shipments SET leg_count = leg_count + 1
    WHERE shipment_id = NEW.shipment_id;
  END IF;
  RETURN NULL;
END $$;

CREATE TRIGGER sf_legs_count_trg
AFTER INSERT OR UPDATE OR DELETE ON sf_legs
FOR EACH ROW EXECUTE FUNCTION sf_leg_count_sync();

CREATE VIEW sf_leg_count_drift AS
SELECT s.shipment_id,
       s.leg_count            AS cached,
       coalesce(c.n, 0)::int  AS actual
FROM sf_shipments s
LEFT JOIN (SELECT shipment_id, count(*) AS n
           FROM sf_legs GROUP BY shipment_id) c
       ON c.shipment_id = s.shipment_id
WHERE s.leg_count IS DISTINCT FROM coalesce(c.n, 0)::int;

