-- v3e04_state_machines_audit/ex6 — generic jsonb-diff audit trigger
CREATE TABLE ticket_audit (
  audit_id  bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  ticket_id bigint NOT NULL,
  op        text   NOT NULL,
  changed   jsonb  NOT NULL,
  previous  jsonb  NOT NULL,
  at        timestamptz NOT NULL DEFAULT now()
);

CREATE FUNCTION ticket_audit_fn() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    INSERT INTO ticket_audit (ticket_id, op, changed, previous)
    VALUES (NEW.ticket_id, 'INSERT', to_jsonb(NEW), '{}'::jsonb);
  ELSIF TG_OP = 'UPDATE' THEN
    INSERT INTO ticket_audit (ticket_id, op, changed, previous)
    VALUES (NEW.ticket_id, 'UPDATE',
            to_jsonb(NEW) - to_jsonb(OLD),
            to_jsonb(OLD) - to_jsonb(NEW));
  ELSE
    INSERT INTO ticket_audit (ticket_id, op, changed, previous)
    VALUES (OLD.ticket_id, 'DELETE', '{}'::jsonb, to_jsonb(OLD));
  END IF;
  RETURN NULL;
END $$;

