-- v3e04_state_machines_audit/challenge — one guarded, atomic transition
CREATE FUNCTION move_ticket(p_ticket_id bigint,
                            p_to_status text,
                            p_actor     text) RETURNS void
LANGUAGE plpgsql AS $$
DECLARE
  v_from text;
BEGIN
  SELECT status INTO v_from
  FROM tickets
  WHERE ticket_id = p_ticket_id
  FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'no such ticket %', p_ticket_id;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM ticket_transitions
                 WHERE from_status = v_from
                   AND to_status   = p_to_status) THEN
    RAISE EXCEPTION 'illegal transition % -> %', v_from, p_to_status;
  END IF;

  INSERT INTO ticket_events (ticket_id, from_status, to_status, actor, at)
  VALUES (p_ticket_id, v_from, p_to_status, p_actor, now());

  UPDATE tickets
  SET status    = p_to_status,
      closed_at = CASE WHEN (SELECT is_terminal FROM ticket_statuses
                             WHERE status = p_to_status)
                       THEN now() ELSE closed_at END
  WHERE ticket_id = p_ticket_id;
END $$;

SELECT move_ticket(10, 'triaged',     'agent:ines');
SELECT move_ticket(10, 'in_progress', 'agent:omar');
SELECT move_ticket(10, 'resolved',    'agent:omar');

