CREATE PROCEDURE backfill_reconciled()
LANGUAGE plpgsql AS $$
DECLARE
  n integer;
BEGIN
  LOOP
    UPDATE ledger_entries
    SET reconciled = true
    WHERE entry_id IN (SELECT entry_id
                       FROM ledger_entries
                       WHERE status = 'settled'
