-- v3e06_online_migrations/ex6 — rename by expand-and-dual-write
ALTER TABLE ledger_entries ADD COLUMN note varchar(50);

CREATE FUNCTION sync_note() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.note IS NULL THEN
      NEW.note := NEW.memo;
    ELSE
      NEW.memo := NEW.note;
    END IF;
  ELSE
    IF NEW.note IS DISTINCT FROM OLD.note THEN
      NEW.memo := NEW.note;
    ELSE
      NEW.note := NEW.memo;
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER ledger_note_sync
BEFORE INSERT OR UPDATE ON ledger_entries
FOR EACH ROW EXECUTE FUNCTION sync_note();

UPDATE ledger_entries SET note = memo
WHERE note IS NULL AND memo IS NOT NULL;

SELECT count(*) FILTER (WHERE note IS NOT DISTINCT FROM memo) AS both_match,
       count(*)                                               AS total
FROM ledger_entries;

