WITH stepped AS (
  SELECT seq, step, node,
         lag(node) OVER (ORDER BY seq) AS prev_node
  FROM rf
)
SELECT step, (node <> prev_node) AS rewrote
FROM stepped
WHERE prev_node IS NOT NULL
ORDER BY seq;

-- v3e06_online_migrations/ex8 — who is blocking whom, and failing fast
CREATE VIEW lock_waits AS
SELECT blocked.pid                        AS blocked_pid,
       blocked.query                      AS blocked_query,
       blocking.pid                       AS blocking_pid,
       blocking.state                     AS blocking_state,
       blocking.query                     AS blocking_query,
       now() - blocking.xact_start        AS blocking_age
FROM pg_stat_activity blocked
CROSS JOIN LATERAL unnest(pg_blocking_pids(blocked.pid)) AS b(pid)
JOIN pg_stat_activity blocking ON blocking.pid = b.pid;

SET lock_timeout = '50ms';

DO $$
BEGIN
  ALTER TABLE ledger_entries ADD COLUMN probe_col int;
  INSERT INTO migration_log (step, note) VALUES ('probe', 'acquired');
EXCEPTION WHEN lock_not_available THEN
