ALTER TABLE ledger_entries ADD COLUMN amount_cents_big bigint;

CREATE FUNCTION sync_amount() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.amount_cents_big IS NULL THEN
      NEW.amount_cents_big := NEW.amount_cents;
    ELSE
      NEW.amount_cents := NEW.amount_cents_big;
    END IF;
  ELSE
    IF NEW.amount_cents_big IS DISTINCT FROM OLD.amount_cents_big THEN
      NEW.amount_cents := NEW.amount_cents_big;
    ELSE
      NEW.amount_cents_big := NEW.amount_cents;
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER ledger_amount_sync
BEFORE INSERT OR UPDATE ON ledger_entries
FOR EACH ROW EXECUTE FUNCTION sync_amount();

CREATE PROCEDURE backfill_amount()
LANGUAGE plpgsql AS $$
DECLARE
  n integer;
BEGIN
  LOOP
    UPDATE ledger_entries
    SET amount_cents_big = amount_cents
    WHERE entry_id IN (SELECT entry_id
                       FROM ledger_entries
                       WHERE amount_cents_big IS NULL
                       ORDER BY entry_id
                       LIMIT 25000);
    GET DIAGNOSTICS n = ROW_COUNT;
    COMMIT;
    EXIT WHEN n = 0;
  END LOOP;
END $$;

CALL backfill_amount();

ALTER TABLE ledger_entries
  ADD CONSTRAINT ledger_amount_big_notnull
  CHECK (amount_cents_big IS NOT NULL) NOT VALID;

ALTER TABLE ledger_entries VALIDATE CONSTRAINT ledger_amount_big_notnull;

ALTER TABLE ledger_entries ALTER COLUMN amount_cents_big SET NOT NULL;

ALTER TABLE ledger_entries DROP CONSTRAINT ledger_amount_big_notnull;

CREATE INDEX CONCURRENTLY ledger_amount_big_idx
  ON ledger_entries (amount_cents_big);

SELECT (SELECT count(*) FROM ledger_entries
        WHERE amount_cents_big IS DISTINCT FROM amount_cents::bigint)
         AS mismatched,
       (SELECT attnotnull FROM pg_attribute
        WHERE attrelid = 'ledger_entries'::regclass
          AND attname = 'amount_cents_big')          AS is_notnull,
       (SELECT indisvalid FROM pg_index
        WHERE indexrelid = 'ledger_amount_big_idx'::regclass)
         AS index_valid;

